GRD_COLS = 12

output = [[5]*GRD_COLS for _ in range(GRD_ROWS)]

for r_src, c_src, val in sources:
    for k in range(GRD_ROWS + GRD_COLS):
        r_output = r_src - k
        c_output = c_src - k
        if r_output >= 0 and c_output >= 0:
            output[r_output][c_output] = val

